1	import "server-only";
2	import { cache } from "react";
3	import {
4	  getLogtoConfig,
5	  mapClaimsToAuthUser,
6	  verifyStoredIdToken,
7	} from "@lib/auth/logto";
8	import { enrichWithBackendProfile } from "@lib/auth/enrichment";
9	import {
10	  getAccessTokenFromCookies,
11	  getIdTokenFromCookies,
12	} from "@utils/auth-cookies";
13	import type { AuthUser } from "types/auth";
14	
15	/**
16	 * Resolve the current authenticated user from the verified id_token cookie.
17	 *
18	 * The id_token yields the Logto `sub` as `user.id`. For creator-ownership
19	 * checks (e.g., "is this user the event creator?"), we need the **backend
20	 * UUID** — which is what `event.owner.id` stores. When an access
21	 * token is available, we enrich via `GET /api/auth/me` to replace `id` with
22	 * the backend UUID (preserving the Logto sub as `logtoId`). The enrichment is
23	 * best-effort: if the backend is unreachable, the id_token-only user is
24	 * returned (creator checks will simply fail with 404/403, not crash).
25	 *
26	 * Returns null when there is no session or the id_token cannot be verified.
27	 */
28	async function getCurrentUserInternal(): Promise<AuthUser | null> {
29	  try {
30	    const idToken = await getIdTokenFromCookies();
31	    if (!idToken) return null;
32	
33	    const config = getLogtoConfig();
34	    const claims = await verifyStoredIdToken(config, idToken);
35	    const user = mapClaimsToAuthUser(claims);
36	
37	    // Enrich with the backend UUID so creator-ownership checks match.
38	    // `enrichWithBackendProfile` handles its own throws for known paths
39	    // (4xx Bearer rejection -> profileEnrichmentFailed: "auth"; 5xx /
40	    // network blip -> silently swallowed so a transient outage doesn't
41	    // visually look like a logout). This try-catch is a last-resort safety
42	    // net for genuinely unforeseen throws around enrichment itself (e.g.
43	    // getAccessTokenFromCookies() failing) — falling back to the bare
44	    // id_token user here is the correct degraded state, since the id_token
45	    // was already verified above. This is distinct from the function-level
46	    // catch below, which covers failures reading/verifying the session
47	    // itself (no id_token to fall back to) and treats those as unauthenticated.
48	    try {
49	      const accessToken = await getAccessTokenFromCookies();
50	      return await enrichWithBackendProfile(user, accessToken);
51	    } catch (enrichError) {
52	      console.error("getCurrentUser: enrichment threw unexpectedly, returning id_token-only user", enrichError);
53	      return user;
54	    }
55	  } catch {
56	    // Any failure to read/verify the session (before we'd have a valid
57	    // id_token-derived user to fall back to) is treated as unauthenticated.
58	    return null;
59	  }
60	}
61	
62	// Wrap in React cache() so multiple server components/actions calling
63	// getCurrentUser() in the same request share a single backend enrichment call
64	// (avoids redundant GET /auth/me round-trips within one request cycle).
65	export const getCurrentUser = cache(getCurrentUserInternal);
66

