14	  pictureSource?: PictureSource;
15	  lastLoginAt?: string;
16	  /**
17	   * True once username + displayName are set. `POST /api/events` 403s while
18	   * this is false — `/publica` gates on it to send the user to complete
19	   * their profile before they fill out the whole event form.
20	   */
21	  profileCompleted?: boolean;
22	  /**
23	   * Not derivable from the public `GET /api/users/{username}` endpoint (it
24	   * 404s for incomplete/temporary profiles — the exact case the edit-profile
25	   * page needs to prefill), so it's carried on the session user instead.
26	   */
27	  bio?: string;
28	  // Original Logto subject identifier, preserved for debugging/auditing.
29	  logtoId?: string;
30	  /**
31	   * Set when the id_token session is valid but the backend enrichment call
32	   * (GET /api/auth/me with `Authorization: Bearer <access_token>`) was
33	   * rejected — i.e. `4xx` (typically `401` because the audience or JWKS
34	   * wiring is wrong). Surfaced in the navbar dropdown so users can tell
35	   * apart "logged out" from "logged in but the backend doesn't accept me".
36	   * Transient failures (5xx / network blip) are intentionally not flagged —
37	   * returning the id_token-only user without this property keeps the session
38	   * visually stable during a brief outage.
39	   */
40	  profileEnrichmentFailed?: "auth";
41	}
